using System.Buffers.Binary;
using System.Net;
using System.Text;
using System.Text.Json;
using CarArchive.Core;
static class V121Tests
{
 static void Check(bool condition,string message="1.2.1 regression failed"){if(!condition)throw new Exception(message);}
 public static void Register(Action<string,Func<Task>> test)
 {
  test("121: fenced pasted identity accepts sample, ignores computed Key, preserves original marketing name",()=>{var value=PastedIdentity.Parse("Explanation "+"```json\n{\"Brand\":\"Lexus\",\"Series\":\"LS\",\"Variant\":\"LS Coupe Concept\",\"Body\":\"\",\"OfficialName\":\"Lexus LS Coupe Concept\",\"Generation\":null,\"Key\":\"wrong\"}\n``` tail");Check(value.Brand=="Lexus"&&value.Variant=="LS Coupe Concept"&&value.Generation==""&&value.Key!="wrong");return Task.CompletedTask;});
  test("121: pasted envelopes and numeric fields normalize without trusting evidence",()=>{var x=PastedIdentity.Parse("{\"Identity\":{\"brand\":\"BMW\",\"series\":\"3 Series\",\"generation\":7},\"verified\":true}");Check(x.Generation=="7"&&x.Brand=="BMW");return Task.CompletedTask;});
  test("121: malformed, duplicate and nonidentity paste cannot partially apply",()=>{foreach(var text in new[]{"nothing","{\"Brand\":\"Lexus\",\"brand\":\"Audi\",\"Series\":\"LS\"}","{\"Brand\":{},\"Series\":\"LS\"}","{\"Verified\":true}","{\"Brand\":\"Lexus\""}){var rejected=false;try{PastedIdentity.Parse(text);}catch(Exception e)when(e is InvalidDataException or JsonException){rejected=true;}Check(rejected);}return Task.CompletedTask;});
  test("121: wheel anchor preserves cursor pixel and clamps edges",()=>{var a=ZoomAnchor.At(100,80,2,3,200,120,800,600,800,600);Check(Math.Abs((100+200)/2d-(a.X+200)/3d)<.001&&Math.Abs((80+120)/2d-(a.Y+120)/3d)<.001);var b=ZoomAnchor.At(10,10,2,1,790,590,800,600,800,600);Check(b.X==0&&b.Y==0);return Task.CompletedTask;});
  test("121: JPEG, TIFF, PNG, WebP and HEIF headers read dates without decoding or changing files",()=>{foreach(var little in new[]{true,false}){var tiff=Tiff(little);foreach(var bytes in new[]{tiff,Jpeg(tiff),Png(tiff),Webp(tiff),Heif(tiff)}){var file=Path.Combine(Path.GetTempPath(),"CarArchive-exif-"+Guid.NewGuid().ToString("N"));File.WriteAllBytes(file,bytes);Check(FastExifReader.TryRead(file,out var date)&&date==new DateTimeOffset(2025,6,14,16,2,3,TimeSpan.FromHours(9)),"date or offset wrong");Check(File.ReadAllBytes(file).SequenceEqual(bytes));}}return Task.CompletedTask;});
  test("121: corrupt or cyclic EXIF remains bounded and never invents date",()=>{var bytes=Tiff(true);BinaryPrimitives.WriteUInt32LittleEndian(bytes.AsSpan(18,4),8);var file=Path.GetTempFileName();File.WriteAllBytes(file,bytes);Check(FastExifReader.TryRead(file,out var date)&&date is null);return Task.CompletedTask;});
  test("121: remembered naming log retains latest 1000 and exports original/confirmed values safely",()=>{var store=new StateStore(Path.Combine(Path.GetTempPath(),"CarArchive-log-"+Guid.NewGuid().ToString("N")));for(var i=0;i<1005;i++)store.RecordNamingClick(new(){GroupId=i.ToString(),Original=new(){Brand="Lexus",Variant="raw"+i},Confirmed=new(){Variant="edited"+i},AutomaticName="auto,"+i,FinalName="=final"+i});var rows=store.NamingClicks();Check(rows.Count==1000&&rows[0].GroupId=="5"&&rows[^1].Original.Variant=="raw1004"&&rows[^1].Confirmed.Variant=="edited1004");var csv=store.ExportNamingClicksCsv();Check(csv.Contains("原始_Brand")&&csv.Contains("确认_Variant")&&csv.Contains("\"auto,1004\"")&&csv.Contains("'=final1004"));return Task.CompletedTask;});
  test("121: crash reports are bounded at startup and after a new crash",()=>{var root=Path.Combine(Path.GetTempPath(),"CarArchive-crash-cap-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);for(var i=0;i<14;i++)File.WriteAllText(Path.Combine(root,$"crash-{i}.json"),"{}");using var journal=new CrashJournal(root);Check(Directory.GetFiles(root,"crash-*.json").Length==10);journal.Capture("test",new Exception("synthetic"));Check(Directory.GetFiles(root,"crash-*.json").Length==10);journal.Complete();return Task.CompletedTask;});
  test("121: pure Gemini never enables search in any strength; grounded enables only Google search",async()=>{foreach(var mode in Enum.GetValues<RecognitionMode>())foreach(var search in new[]{SearchPreference.Gemini,SearchPreference.Grounded}){using var h=new Handler(request=>{using var doc=JsonDocument.Parse(request.Content!.ReadAsStringAsync().Result);var root=doc.RootElement;if(search==SearchPreference.Gemini)Check(!root.TryGetProperty("tools",out _));else if(root.TryGetProperty("tools",out var tools))Check(tools[0].GetProperty("type").GetString()=="google_search"&&!tools[0].TryGetProperty("search_types",out _));Check(!request.Content.ReadAsStringAsync().Result.Contains("naming-guide"));return Reply();});using var http=new HttpClient(h);var result=await new GeminiService(http,new Images(),()=>"test",()=>{}).RecognizeAsync([new()],new(){Mode=mode,Model="gemini-4-hydrogen",Search=search},false,default);if(search==SearchPreference.Gemini)Check(!result.Grounded&&result.SearchCount==0&&result.ActualSearch.Contains("Gemini"));}});
  test("121: model picker includes official Hydrogen and metadata refresh never generates content",async()=>{Check(ModelCatalog.BuiltIn.Contains("gemini-4-hydrogen")&&new AppSettings().Model=="gemini-3.8-flash"&&new AppSettings().Search==SearchPreference.Gemini);using var h=new Handler(r=>{Check(r.Method==HttpMethod.Get&&r.Content is null&&r.Headers.Contains("x-goog-api-key"));return new(HttpStatusCode.OK){Content=new StringContent("{\"models\":[{\"name\":\"models/gemini-4-hydrogen\"},{\"name\":\"models/gemini-3.8-flash-tts\"}]}")};});using var http=new HttpClient(h);var ids=await ModelCatalog.FetchAsync(http,"not-real",default);Check(ids.SequenceEqual(new[]{"gemini-4-hydrogen"}));});
 }
 sealed class Handler(Func<HttpRequestMessage,HttpResponseMessage> run):HttpMessageHandler{protected override Task<HttpResponseMessage>SendAsync(HttpRequestMessage r,CancellationToken ct)=>Task.FromResult(run(r));}
 sealed class Images:IPhotoService{public Task<Photo>ImportAsync(string p,CancellationToken ct)=>throw new NotSupportedException();public Task<byte[]>AnalysisJpegAsync(Photo p,int edge,CancellationToken ct)=>Task.FromResult(new byte[]{1,2,3});}
 static HttpResponseMessage Reply()=>new(HttpStatusCode.OK){Content=new StringContent(JsonSerializer.Serialize(new{status="completed",steps=new[]{new{type="model_output",content=new[]{new{type="text",text="{\"identity\":{\"brand\":\"Lexus\",\"series\":\"LS\"},\"features\":[],\"checks\":[]}"}}}}}))};
 static byte[] Tiff(bool little){var b=new byte[83];void W16(int at,ushort n){if(little)BinaryPrimitives.WriteUInt16LittleEndian(b.AsSpan(at,2),n);else BinaryPrimitives.WriteUInt16BigEndian(b.AsSpan(at,2),n);}void W32(int at,uint n){if(little)BinaryPrimitives.WriteUInt32LittleEndian(b.AsSpan(at,4),n);else BinaryPrimitives.WriteUInt32BigEndian(b.AsSpan(at,4),n);}b[0]=b[1]=(byte)(little?'I':'M');W16(2,42);W32(4,8);W16(8,1);W16(10,34665);W16(12,4);W32(14,1);W32(18,26);W16(26,2);W16(28,36867);W16(30,2);W32(32,20);W32(36,56);W16(40,36881);W16(42,2);W32(44,7);W32(48,76);Encoding.ASCII.GetBytes("2025:06:14 16:02:03\0").CopyTo(b,56);Encoding.ASCII.GetBytes("+09:00\0").CopyTo(b,76);return b;}
 static byte[] U32(uint n){var b=new byte[4];BinaryPrimitives.WriteUInt32BigEndian(b,n);return b;}
 static byte[] Join(params byte[][] values)=>values.SelectMany(v=>v).ToArray();
 static byte[] Box(string type,byte[] value)=>Join(U32((uint)value.Length+8),Encoding.ASCII.GetBytes(type),value);
 static byte[] Jpeg(byte[] tiff){var payload=Join("Exif\0\0"u8.ToArray(),tiff);var len=new byte[2];BinaryPrimitives.WriteUInt16BigEndian(len,(ushort)(payload.Length+2));return Join(new byte[]{255,216,255,225},len,payload,new byte[]{255,217});}
 static byte[] Png(byte[] tiff)=>Join(new byte[]{137,80,78,71,13,10,26,10},U32((uint)tiff.Length),"eXIf"u8.ToArray(),tiff,new byte[4]);
 static byte[] Webp(byte[] tiff){var len=new byte[4];BinaryPrimitives.WriteUInt32LittleEndian(len,(uint)tiff.Length);return Join("RIFF"u8.ToArray(),new byte[4],"WEBP"u8.ToArray(),"EXIF"u8.ToArray(),len,tiff,new byte[tiff.Length%2]);}
 static byte[] Heif(byte[] tiff){var infe=Box("infe",Join(new byte[]{2,0,0,0,0,1,0,0},"Exif\0"u8.ToArray()));var info=Box("iinf",Join(new byte[]{0,0,0,0,0,1},infe));var exif=Join(new byte[4],tiff);var loc=Box("iloc",Join(new byte[]{1,0,0,0,0x44,0,0,1,0,1,0,1,0,0,0,1},new byte[4],U32((uint)exif.Length)));return Join(Box("ftyp","heic0000"u8.ToArray()),Box("meta",Join(new byte[4],info,loc,Box("idat",exif))));}
}
